import { useState } from 'react';
import { Button, ButtonGroup, Calendar, Card, Stack } from '@jinx-ui/react';

type ReportDatePickerProps = {
  defaultValue?: Date;
  onChange: (date: Date) => void;
};

const startOfDay = (date: Date): Date =>
  new Date(date.getFullYear(), date.getMonth(), date.getDate());

const daysAgo = (days: number): Date => {
  const date = startOfDay(new Date());
  date.setDate(date.getDate() - days);
  return date;
};

const isSameDay = (a: Date, b: Date): boolean =>
  a.getFullYear() === b.getFullYear() &&
  a.getMonth() === b.getMonth() &&
  a.getDate() === b.getDate();

const presets = [
  { id: 'today', label: 'Сегодня', days: 0 },
  { id: 'yesterday', label: 'Вчера', days: 1 },
  { id: 'week', label: 'Неделя назад', days: 7 },
];

export default function ReportDatePicker({ defaultValue, onChange }: ReportDatePickerProps) {
  const [selected, setSelected] = useState<Date>(() => startOfDay(defaultValue ?? new Date()));

  const select = (date: Date): void => {
    const normalized = startOfDay(date);
    setSelected(normalized);
    onChange(normalized);
  };

  return (
    <Card>
      <Stack gap="md">
        <ButtonGroup aria-label="Быстрый выбор даты отчёта">
          {presets.map((preset) => (
            <Button
              key={preset.id}
              variant={isSameDay(selected, daysAgo(preset.days)) ? 'primary' : 'secondary'}
              onClick={() => select(daysAgo(preset.days))}
            >
              {preset.label}
            </Button>
          ))}
        </ButtonGroup>
        <Calendar value={selected} onChange={select} />
      </Stack>
    </Card>
  );
}

